"""Isotope pattern calculator via exact polynomial convolution."""

from collections import defaultdict

# Inline isotope tables: element -> {nominal mass shift: abundance}
ISOTOPES = {
    "Cl": {0: 0.7576, 2: 0.2424},
    "Br": {0: 0.5069, 2: 0.4931},
    "C":  {0: 0.9893, 1: 0.0107},
    # H and O treated as monoisotopic
    "H":  {0: 1.0},
    "O":  {0: 1.0},
}


def _poly_mult(p, q):
    """Exact convolution of two polynomials given as dict {exponent: coeff}."""
    out = defaultdict(float)
    for e1, c1 in p.items():
        for e2, c2 in q.items():
            out[e1 + e2] += c1 * c2
    return dict(out)


def pattern(counts: dict) -> list:
    """Compute the isotope pattern for a formula given as {element: count}.

    Returns a list of (nominal mass shift, relative intensity) tuples sorted
    by mass shift, normalized so the most intense peak has intensity 100.
    """
    total = defaultdict(lambda: {0: 1.0})
    poly = {0: 1.0}
    for el, n in counts.items():
        iso = ISOTOPES[el]
        base = poly
        for _ in range(n):
            poly = _poly_mult(poly, iso)
    m = max(poly.values())
    return sorted((shift, 100.0 * c / m) for shift, c in poly.items())

